from sqlalchemy.orm import Session

from .. import prompts
from ..llm.client import LLMClient
from ..models import Case, Document
from ..rag.retriever import RetrievalIndexError, get_retriever, retrieve
from ..schemas import DocumentLLM
from . import case_service
from .citations import normalize_tags, unverified_mentions
from .guidance_service import guidance_query

DRAFT_BANNER = {
    "en": "DRAFT — generated by NyayaAI for your review. Verify every fact, fill in all [PLACEHOLDERS], and consider "
          "consulting a qualified lawyer before sending. This is not legal advice.",
    "hi": "ड्राफ्ट — NyayaAI द्वारा आपकी समीक्षा के लिए तैयार। भेजने से पहले हर तथ्य की जाँच करें, सभी [PLACEHOLDERS] भरें, "
          "और ज़रूरत हो तो किसी योग्य वकील से सलाह लें। यह कानूनी सलाह नहीं है।",
}
TITLES = {
    "seller_complaint": {"en": "Complaint to Seller", "hi": "विक्रेता को शिकायत"},
    "refund_request": {"en": "Refund Request", "hi": "रिफंड अनुरोध"},
    "consumer_grievance": {"en": "Consumer Grievance (Draft)", "hi": "उपभोक्ता शिकायत (ड्राफ्ट)"},
    "statement_of_facts": {"en": "Chronological Statement of Facts", "hi": "घटनाओं का क्रमवार विवरण"},
}
FACT_LABELS = {
    "en": {"seller_name": "Seller / company", "platform": "Platform", "product_details": "Product",
           "order_id": "Order ID", "purchase_date": "Purchase date", "delivery_date": "Delivery date",
           "amount_paid": "Amount paid", "previous_communication": "Communication with seller",
           "desired_resolution": "Resolution sought", "evidence": "Evidence available"},
    "hi": {"seller_name": "विक्रेता / कंपनी", "platform": "प्लेटफ़ॉर्म", "product_details": "उत्पाद",
           "order_id": "ऑर्डर आईडी", "purchase_date": "खरीद की तारीख", "delivery_date": "डिलीवरी की तारीख",
           "amount_paid": "भुगतान राशि", "previous_communication": "विक्रेता से बातचीत",
           "desired_resolution": "माँगा गया समाधान", "evidence": "उपलब्ध सबूत"},
}


def statement_of_facts(case: Case, language: str) -> str:
    """Deterministic: built only from stored case fields and timeline — nothing generated."""
    L = FACT_LABELS[language]
    lines = [TITLES["statement_of_facts"][language].upper(), "", f"Case: {case.title}", ""]
    for key, label in L.items():
        v = getattr(case, key)
        if isinstance(v, list):
            v = "; ".join(v) if v else None
        lines.append(f"{label}: {v if v else '[NOT PROVIDED]'}")
    lines += ["", "Timeline:" if language == "en" else "घटनाक्रम:"]
    if case.events:
        for i, e in enumerate(case.events, start=1):
            lines.append(f"{i}. {e.date or '[date not stated]'} — {e.description}")
    else:
        lines.append("[No timeline recorded yet]")
    if case.description:
        lines += ["", ("Summary of dispute: " if language == "en" else "विवाद का सार: ") + case.description]
    lines += ["", "Declaration: I state that the above facts are true to the best of my knowledge.",
              "Name: [YOUR FULL NAME]    Signature: ____________    Date: " + date.today().strftime("%d %B %Y")]
    return "\n".join(lines)


NUMBER_WORDS = {
    "two": 2, "three": 3, "seven": 7, "ten": 10, "fourteen": 14, "fifteen": 15, "twenty-one": 21, "thirty": 30,
    "forty-five": 45, "forty-eight": 48, "forty eight": 48, "sixty": 60, "ninety": 90, "one month": 30,
}


def _corpus_titles() -> str:
    try:
        return " ".join({c.get("part_title") or c["doc_title"] for c in get_retriever().chunks})
    except RetrievalIndexError:
        return ""


def number_check(body: str, case: Case, sources: list[dict], today: str) -> list[str]:
    """Numbers in the draft that do not appear in the case record, the retrieved sources (incl. numbers written
    as words in the statute, e.g. "forty-eight hours"), official document titles, or today's date."""
    source_text = " ".join(" ".join((s["excerpt"], s["title"], s["label"])) for s in sources)
    allowed_text = " ".join([
        json.dumps(case_service.case_facts(case), ensure_ascii=False),
        json.dumps(case_service.timeline(case), ensure_ascii=False),
        source_text, _corpus_titles(), today,
    ])
    allowed = {re.sub(r",", "", n) for n in re.findall(r"\d[\d,]*", allowed_text)}
    low = source_text.lower()
    allowed |= {str(v) for w, v in NUMBER_WORDS.items() if w in low}
    found = []
    for n in re.findall(r"\d[\d,]*", body):
        k = re.sub(r",", "", n).strip(",")
        if len(k) >= 2 and k not in allowed and n not in found:
            found.append(n)
    return found


def generate_document(db: Session, case: Case, llm: LLMClient, doc_type: str, language: str) -> Document:
    today = date.today().strftime("%d %B %Y")
    if doc_type == "statement_of_facts":
        body = statement_of_facts(case, language)
        title = TITLES[doc_type][language]
        sources: list[dict] = []
        checks = {"generator": "deterministic (no LLM)", "unverified_mentions": [], "unknown_numbers": [],
                  "placeholders": len(re.findall(r"\[[A-Z][A-Z _/]+\]", body))}
    else:
        category = case.category if case.category not in (None, "unclear", "out_of_scope") else None
        sources = retrieve(guidance_query(case), top_k=6, category=category)
        out = llm.complete_json(
            prompts.document_messages(doc_type, case_service.case_facts(case), case_service.timeline(case),
                                      language, sources, today),
            DocumentLLM, temperature=0.2, max_tokens=2500)
        body = re.sub(r"\s*\[S\d{1,2}\]", "", normalize_tags(out.body)).strip()
        title = out.title.strip() or TITLES[doc_type][language]
        checks = {
            "generator": "llm",
            "unverified_mentions": unverified_mentions(body, sources),
            "unknown_numbers": number_check(body, case, sources, today),
            "placeholders": len(re.findall(r"\[[^\]\n]{2,40}\]", body)),
        }
        mentioned = body.lower()
        sources = [s for s in sources if s["label"].lower() in mentioned or s["short"].lower() in mentioned] or []

    content = f"{DRAFT_BANNER[language]}\n{'=' * 60}\n\n{body}\n"
    doc = Document(case=case, doc_type=doc_type, title=title[:255], content=content, language=language,
                   sources=sources, checks=checks)
    db.add(doc)
    db.commit()
    db.refresh(doc)
    return doc
